 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            top = min(y for y, _ in cells)
            bottom = max(y for y, _ in cells)
            left = min(x for _, x in cells)
            right = max(x for _, x in cells)
            bands = {}
            for y, x in cells:
                depth = min(y-top, bottom-y, x-left, right-x)
                bands.setdefault(depth, set()).add(grid[y][x])
            depths = sorted(bands)
            # Each concentric rectangular band has one color; reverse the band palette.
            colors = [next(iter(bands[d])) for d in depths]
            if any(len(bands[d]) != 1 for d in depths):
                continue
            mapping = {d: colors[len(colors)-1-i] for i, d in enumerate(depths)}
            for y, x in cells:
                depth = min(y-top, bottom-y, x-left, right-x)
                out[y][x] = mapping[depth]
    return out
